style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://i.imgur.com/Mn6nhtD.jpg"); /* Substitua pela sua imagem hospedada */
        background-size: cover;
        background-attachment: fixed;
        background-repeat: no-repeat;
        background-position: center;
        color: #f8e8ff; /* texto claro */
        font-family: 'Orbitron', sans-serif !important;
    }

    a {
        color: #cfa3ff !important;
    }

    a:hover {
        color: #ffffff !important;
        text-shadow: 0 0 8px #e2baff;
    }

    header, nav, footer, .sidebar, .ad-banner {
        background: rgba(0, 0, 0, 0.6) !important;
        border: none !important;
    }

    .content, main, article, section, div {
        background: rgba(15, 5, 25, 0.5) !important;
        backdrop-filter: blur(5px);
        border-radius: 12px;
        padding: 10px;
    }

    ::selection {
        background: #a065ff;
        color: #fff;
    }

    /* Scrollbar estilo cósmico */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: rgba(0, 0, 0, 0.2);
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(#e6ccff, #a96dff);
        border-radius: 10px;
    }

    h1, h2, h3, h4 {
        color: #ffd6ff !important;
        text-shadow: 0 0 5px #b076ff;
    }
}
